app.get('/api/admin/dashboard',async(req,res)=>{let [a,b,c,d]=await Promise.all([pool.query("select count(*) c,coalesce(sum(total),0) sales from orders where status='COMPLETED' and created_at::date=current_date"),pool.query("select count(*) c from orders where status='PENDING'"),pool.query('select count(*) c from products'),pool.query('select * from orders order by created_at desc limit 12')]);res.json({todayOrders:+a.rows[0].c,todaySales:+a.rows[0].sales,pending:+b.rows[0].c,products:+c.rows[0].c,recent:d.rows})});
