app.patch('/api/admin/orders/:id/status',async(req,res)=>{const allowed=['CONFIRMED','PREPARING','READY','COMPLETED','REJECTED','CANCELLED'];let s=String(req.body.status||'');if(!allowed.includes(s))return res.status(400).json({error:'Invalid status'});let r=await pool.query('update orders set status=$1,status_note=$2,estimated_minutes=$3,updated_at=now() where id=$4 returning *',[s,String(req.body.note||'').slice(0,300),req.body.estimatedMinutes?Math.max(1,Math.min(240,+req.body.estimatedMinutes)):null,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'Not found'});await pool.query('insert into order_history(order_id,status,note) values($1,$2,$3)',[req.params.id,s,String(req.body.note||'').slice(0,300)]);res.json({order:r.rows[0]})});
